package com.hrcoresystem.hrcore_api.modules.tenant.incidents.infrastructure.persistence;
import com.hrcoresystem.hrcore_api.modules.tenant.incidents.domain.model.IncidentModels.*; import jakarta.persistence.*; import java.time.*; import java.util.UUID; import lombok.Getter; import lombok.Setter;
@Entity @Table(name="employee_incidents") @Getter @Setter public class IncidentEntity { @Id UUID id; @Column(name="employee_id",nullable=false) UUID employeeId; @Column(name="employment_period_id",nullable=false) UUID employmentPeriodId; @Column(name="incident_number",nullable=false,unique=true) String incidentNumber; @Enumerated(EnumType.STRING) @Column(name="incident_type") Type incidentType; @Enumerated(EnumType.STRING) Severity severity; String title; @Column(columnDefinition="TEXT") String description; @Column(name="occurred_at") Instant occurredAt; String location; @Enumerated(EnumType.STRING) Status status; @Column(name="reported_by") UUID reportedBy; @Column(name="assigned_to") UUID assignedTo; @Column(name="employee_response",columnDefinition="TEXT") String employeeResponse; @Column(name="employee_response_at") Instant employeeResponseAt; @Column(columnDefinition="TEXT") String resolution; Instant resolvedAt; Instant closedAt; @Column(name="created_at") Instant createdAt; @Column(name="updated_at") Instant updatedAt; @PrePersist void create(){if(createdAt==null)createdAt=Instant.now();updatedAt=Instant.now();} @PreUpdate void update(){updatedAt=Instant.now();} }
